<script setup lang="ts">import {ref} from 'vue';import {api} from '../lib/api';const emit=defineEmits<{authenticated:[]}>();const register=ref(false);const email=ref('');const password=ref('');const error=ref('');async function submit(){try{const result=await api<{token:string}>(register.value?'/auth/register':'/auth/login',{method:'POST',body:JSON.stringify({email:email.value,password:password.value})});localStorage.setItem('know_token',result.token);emit('authenticated')}catch(e){error.value='Could not authenticate. Use a valid email and a password of at least 12 characters.'}}</script>
<template><section class="auth card" aria-labelledby="auth-title"><p class="eyebrow">YOUR PRIVATE WORKSPACE</p><h1 id="auth-title">{{register?'Create account':'Welcome back'}}</h1><p class="lede">Keep the things you learn, do, and remember in one place.</p><form @submit.prevent="submit"><label>Email<input v-model="email" type="email" required aria-label="Email"></label><label>Password<input v-model="password" type="password" minlength="12" required aria-label="Password"></label><button class="primary">{{register?'Create account':'Sign in'}}</button></form><p v-if="error" class="notice" role="alert">{{error}}</p><button class="text-button" @click="register=!register">{{register?'Already have an account? Sign in':'New here? Create an account'}}</button></section></template>
